def add_final(c):
 f=dict(id='nouns-final-v1',version=1,assessment='scored',capability='nouns_final_v1',rewardQuizId='lesson:lesson-5',resultKey='assessment:nouns-final-v1',passPercent=80,questionCount=24,questions=[],contexts={})
 c['finalTest']=f
 def Q(category,prompt,opts,refs,context=None):
  n=len(f['questions'])+1;answer='o'+str((n-1)%4)
  # Correct option positions vary in the source, and the UI also shuffles options.
  ids=['o'+str(i) for i in range(4)];ids.remove(answer)
  options=[dict(id=answer,text=S(opts[0][0]) if isinstance(opts[0][0],str) else opts[0][0],feedback=opts[0][1])]+[dict(id=id,text=S(text) if isinstance(text,str) else text,feedback=why) for id,(text,why) in zip(ids,opts[1:])]
  options.sort(key=lambda o:o['id'])
  q=dict(id=f'nouns-final-v1-q{n:02}',type='choice',skill=category,category=category,prompt=prompt,answerId=answer,options=options,ruleRefs=refs)
  if context:q['context']=context
  f['questions'].append(q)
